refentry.refsect1:
  &reftitle.examples;



    Exemplo de property_exists


<?php

class myClass {
    public $mine;
    private $xpto;
    static protected $test;

    static function test() {
        var_dump(property_exists('myClass', 'xpto')); //true
    }
}

var_dump(property_exists('myClass', 'mine'));   //true
var_dump(property_exists(new myClass, 'mine')); //true
var_dump(property_exists('myClass', 'xpto'));   //true
var_dump(property_exists('myClass', 'bar'));    //false
var_dump(property_exists('myClass', 'test'));   //true
myClass::test();

?>





   property_exists retorna &true; independentemente da visibilidade da propriedade,
   detecta propriedades dinâmicas adicionadas às instâncias (quando a classe usa
   #[AllowDynamicProperties]) e ignora os métodos mágicos
   __isset
   e __get.




    Visibilidade, propriedades dinâmicas e métodos mágicos


<?php

#[AllowDynamicProperties]
class MyClass {
    public $public;
    private $private;
    static protected $protectedStatic;

    // ignorado por property_exists
    public function __isset(string $name): bool {
        return true;
    }

    // ignorado por property_exists
    public function __get(string $name): string {
        return '';
    }
}

$instance = new MyClass();
$instance->instanced = 'abc';

var_dump(property_exists($instance, 'public'));          // true  (public)
var_dump(property_exists($instance, 'private'));         // true  (visibilidade ignorada)
var_dump(property_exists($instance, 'protectedStatic')); // true  (visibilidade ignorada)
var_dump(property_exists($instance, 'instanced'));       // true  (propriedade dinâmica na instância)
var_dump(property_exists($instance, 'undefined'));       // false (não declarada, __isset ignorado)

var_dump(property_exists(MyClass::class, 'public'));    // true
var_dump(property_exists(MyClass::class, 'instanced')); // false (propriedades dinâmicas não pertencem à classe)
var_dump(property_exists(MyClass::class, 'undefined')); // false

?>


    &example.outputs;


bool(true)
bool(true)
bool(true)
bool(true)
bool(false)
bool(true)
bool(false)
bool(false)

&reftitle.notes;
&note.uses-autoload;



  A função property_exists não consegue detectar propriedades
  que são magicamente acessíveis usando o método mágico
  __get.
